-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
    match = {
        class = "tag:multimedia_video*",
    },
    no_blur = true,
    opacity = 1.0,
})

hl.window_rule({
    match = {
        class = "tag:settings*",
    },
    opacity = 0.8,
})

hl.window_rule({
    match = {
        class = "class:^(org.gnome.Nautilus)$",
    },
    opacity = 0.8,
})

hl.window_rule({
    match = {
        class = "class:^(gedit|org.gnome.TextEditor|mousepad)$",
    },
    opacity = 0.9,
})

hl.window_rule({
    match = {
        class = "class:^(org.pulseaudio.pavucontrol)$",
    },
    opacity = 0.9,
})

hl.window_rule({
    match = {
        class = "class:^(kitty)$",
    },
    opacity = 0.9,
})

hl.window_rule({
    match = {
        class = "class:^(discord|vesktop|org.telegram.desktop)$",
    },
    opacity = "0.85 override 0.7 override 1 override",
})

hl.window_rule({
    match = {
        class = "class:^(Spotify)$",
    },
    opacity = "0.8 override 0.6 override 1 override",
})

hl.window_rule({
    match = {
        class = "class:^(zen)$",
    },
    opacity = "0.9 override 0.7 override 1 override",
})

