--FLOAT
hl.window_rule({
    match = {
        class = "tag:settings*",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "tag:viewer*",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "tag:multimedia_video*",
    },
    float = true,
    size = "900 506",
})

hl.window_rule({
    match = {
        class = "class:^(org.pulseaudio.pavucontrol)$",
    },
    float = true,
    size = "50% 60%",
})

-- Ignore maximize requests from apps. You'll probably like this.
hl.window_rule({
    match = {
        class = "class:.*",
    },
    suppress_event = "maximize",
})

-- Fix some dragging issues with XWayland
hl.window_rule({
    match = {
        class = "^$",
        title = "^$",
        xwayland = true,
        float = true,
        fullscreen = false,
        pin = false,
    },
    no_focus = true,
})

-- POP UPS AND DIALOGUES
hl.window_rule({
    match = {
        class = "title:^(Save As|Save a File|Pick Files)$",
    },
    float = true,
    size = "50% 60%",
    center = true,
})

hl.window_rule({
    match = {
        class = "initialTitle:(Open Files)",
    },
    float = true,
    size = "70% 60%",
})

